const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'summary',
  index: 8,
  title: 'Key Takeaways: What Separates Winners in Act Two'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Key Takeaways: What Separates Winners in Act Two", {
    x: 0.5, y: 0.25, w: 9, h: 0.7,
    fontSize: 22, fontFace: "Georgia",
    color: theme.primary, bold: true, fit: "shrink"
  });

  // Thin accent line below title
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 0.95, w: 1.2, h: 0.04,
    fill: { color: theme.accent }
  });

  const takeaways = [
    { num: "1", text: "Retention is the critical challenge \u2014 AI-first apps at 14% median vs. 51% for incumbents, a 3.6\u00d7 disadvantage" },
    { num: "2", text: "Foundation models should be a component, not the whole product" },
    { num: "3", text: "Multi-modal, workflow-integrated solutions will win" },
    { num: "4", text: "The >$1B revenue milestone proves real demand exists despite hype-cycle skepticism" },
    { num: "5", text: "Companies solving end-to-end human problems \u2014 not building thin wrappers \u2014 will define Act 2" }
  ];

  const startY = 1.2;
  const rowH = 0.78;

  takeaways.forEach((item, i) => {
    const y = startY + i * rowH;

    // Alternating row background
    if (i % 2 === 0) {
      slide.addShape(pres.shapes.RECTANGLE, {
        x: 0.4, y: y, w: 8.9, h: rowH,
        fill: { color: theme.light }
      });
    }

    // Number badge
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.55, y: y + 0.14, w: 0.45, h: 0.45,
      fill: { color: theme.accent },
      rectRadius: 0.05
    });
    slide.addText(item.num, {
      x: 0.55, y: y + 0.14, w: 0.45, h: 0.45,
      fontSize: 18, fontFace: "Georgia",
      color: "FFFFFF", bold: true,
      align: "center", valign: "middle"
    });

    // Takeaway text
    slide.addText(item.text, {
      x: 1.2, y: y + 0.05, w: 7.9, h: rowH - 0.1,
      fontSize: 13, fontFace: "Calibri",
      color: theme.primary, bold: false,
      valign: "middle", margin: 0
    });
  });

  // Source note
  slide.addText("Based on Sequoia Capital analysis, September 2023", {
    x: 0.5, y: 5.2, w: 5, h: 0.3,
    fontSize: 9, fontFace: "Calibri",
    color: theme.secondary, italic: true
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("8", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "2b2d42",
    secondary: "8d99ae",
    accent: "ef233c",
    light: "edf2f4",
    bg: "FFFFFF"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-08-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

